begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select no_plan();
insert into auth.users(id,email) values ('19000000-0000-4000-8000-000000000001','youtube-fixture@paceon.example');
select has_table('private','youtube_connections','Tokens are in private schema');
set local role anon;
select throws_ok($$select public.youtube_connection_command('{}')$$,'42501',null,'Anonymous cannot execute token RPC');
select throws_ok($$select * from private.youtube_connections$$,'42501',null,'Anonymous cannot read token table');
reset role;
set local role authenticated;
select set_config('request.jwt.claim.sub','19000000-0000-4000-8000-000000000001',true);
select throws_ok($$select public.youtube_connection_command('{}')$$,'42501',null,'Authenticated owner cannot execute token RPC');
select throws_ok($$select * from private.youtube_connections$$,'42501',null,'Authenticated owner cannot read token table');
reset role;
set local role service_role;
select lives_ok($$select youtube_connection_command('{"action":"begin","userId":"19000000-0000-4000-8000-000000000001","generation":"29000000-0000-4000-8000-000000000001","stateHash":"state-one","bindingHash":"browser-one","verifier":"encrypted-verifier"}')$$,'Server can begin OAuth');
select is(youtube_connection_command('{"action":"consume","stateHash":"state-one","bindingHash":"wrong-browser"}'),null::jsonb,'Wrong browser cannot consume state');
select is(youtube_connection_command('{"action":"consume","stateHash":"state-one","bindingHash":"browser-one"}')->>'user_id','19000000-0000-4000-8000-000000000001','State binds callback to original authenticated user');
select is(youtube_connection_command('{"action":"consume","stateHash":"state-one","bindingHash":"browser-one"}'),null::jsonb,'State replay rejected');
select is(youtube_connection_command('{"action":"commit","userId":"19000000-0000-4000-8000-000000000001","generation":"29000000-0000-4000-8000-000000000001","tokens":"encrypted-one"}'),'true'::jsonb,'Consumed callback can commit once');
select is(youtube_connection_command('{"action":"commit","userId":"19000000-0000-4000-8000-000000000001","generation":"29000000-0000-4000-8000-000000000001","tokens":"encrypted-replayed"}'),'false'::jsonb,'Callback commit replay rejected');
select is(youtube_connection_command('{"action":"refresh","userId":"19000000-0000-4000-8000-000000000001","generation":"29000000-0000-4000-8000-000000000001","previous":"wrong-ciphertext","tokens":"encrypted-new"}'),'false'::jsonb,'Refresh compares previous ciphertext');
select is(youtube_connection_command('{"action":"refresh","userId":"19000000-0000-4000-8000-000000000001","generation":"29000000-0000-4000-8000-000000000001","previous":"encrypted-one","tokens":"encrypted-two"}'),'true'::jsonb,'Current refresh succeeds');
select youtube_connection_command('{"action":"begin","userId":"19000000-0000-4000-8000-000000000001","generation":"29000000-0000-4000-8000-000000000002","stateHash":"state-two","bindingHash":"browser-two","verifier":"encrypted-verifier-two"}');
select is(youtube_connection_command('{"action":"refresh","userId":"19000000-0000-4000-8000-000000000001","generation":"29000000-0000-4000-8000-000000000001","previous":"encrypted-two","tokens":"stale"}'),'false'::jsonb,'Old generation refresh cannot overwrite reconnect');
select is(youtube_connection_command('{"action":"commit","userId":"19000000-0000-4000-8000-000000000001","generation":"29000000-0000-4000-8000-000000000001","tokens":"stale"}'),'false'::jsonb,'Old generation callback cannot overwrite reconnect');
reset role;
update private.youtube_connections set state_expires=now()-interval '1 second';
set local role service_role;
select is(youtube_connection_command('{"action":"consume","stateHash":"state-two","bindingHash":"browser-two"}'),null::jsonb,'Expired state rejected');
select is(youtube_connection_command('{"action":"disconnect","userId":"19000000-0000-4000-8000-000000000001"}')->>'tokens','encrypted-two','Disconnect returns token only to trusted revoker');
select is(youtube_connection_command('{"action":"get","userId":"19000000-0000-4000-8000-000000000001"}'),null::jsonb,'Disconnect deletes credentials');
select is(youtube_connection_command('{"action":"refresh","userId":"19000000-0000-4000-8000-000000000001","generation":"29000000-0000-4000-8000-000000000002","previous":"encrypted-two","tokens":"stale"}'),'false'::jsonb,'Refresh after disconnect cannot resurrect');
select is(youtube_connection_command('{"action":"commit","userId":"19000000-0000-4000-8000-000000000001","generation":"29000000-0000-4000-8000-000000000002","tokens":"stale"}'),'false'::jsonb,'Callback after disconnect cannot resurrect');
reset role;
select * from finish();
rollback;
